protocol ItemSource {
    associatedtype Item
    var item: Item { get }
}
struct Box<Value>: ItemSource {
    let item: Value
}
struct CountSource: ItemSource {
    let item: Int
}
func pair<A: ItemSource, B: ItemSource>(_ a: A, _ b: B) -> [A.Item]
where A.Item == B.Item {
    return [a.item, b.item]
}
print(pair(Box(item: 3), Box(item: 8)))
print(pair(Box(item: "east"), Box(item: "west")))

