enum EntryProblem: Error {
    case missing
    case tooLong
}
func checkedName(_ text: String) -> Result<String, EntryProblem> {
    if text.isEmpty { return .failure(.missing) }
    if text.count > 5 { return .failure(.tooLong) }
    return .success(text)
}
func describe(_ result: Result<String, EntryProblem>) -> String {
    switch result {
    case .success(let name):
        return "saved:" + name
    case .failure(.missing):
        return "missing"
    case .failure(.tooLong):
        return "too long"
    }
}
print(describe(checkedName("fern")))
print(describe(checkedName("")))

